  height: 18px;
  margin-top: -6px;
  border-radius: 999px;
  background-color: var(--color-surface-0, #f3f6fb);
  border: 2px solid var(--color-brand-600, #5b66e8);
  box-shadow: var(--shadow-soft, 0 1px 4px rgb(16 24 42 / 0.3));
  transition: transform 0.12s ease;
}

