  font-size: 11px;
  line-height: 1.4;
}

/* ================================ Slider ================================== */

.vault-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 20px;
  background: transparent;
  cursor: pointer;
}

.vault-slider::-webkit-slider-runnable-track {
  height: 6px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    var(--color-brand-600, #5b66e8) var(--vault-slider-fill, 50%),
    var(--color-surface-200, #d3dae8) var(--vault-slider-fill, 50%)
  );
  box-shadow: var(--shadow-inset, inset 0 1px 3px rgb(16 24 42 / 0.14));
}

.vault-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  margin-top: -6px;
  border-radius: 999px;
  background-color: var(--color-surface-0, #f3f6fb);
  border: 2px solid var(--color-brand-600, #5b66e8);
  box-shadow: var(--shadow-soft, 0 1px 4px rgb(16 24 42 / 0.3));
